import{R as c,a as m,s as f}from"./authService-FkTjPsGX.js";document.addEventListener("DOMContentLoaded",()=>{const s=document.getElementById("faceEmail"),u=document.getElementById("faceNovaSenha"),i=document.getElementById("btnBackLogin");i&&i.addEventListener("click",()=>{window.location.href=c.login});const r=document.getElementById("emailForm"),v=document.getElementById("recoveryEmail"),a=r.querySelector("button[type=submit]");r.addEventListener("submit",async t=>{t.preventDefault();const e=v.value.trim();a.disabled=!0,a.textContent="Enviando...";const{error:o}=await m.resetPassword(e);if(o){alert(`Não foi possível enviar o e-mail: ${o.message}`),a.disabled=!1,a.textContent="Enviar e-mail para Redefinir";return}s.innerHTML=`
            <div class="brand">
                <i class="fas fa-envelope-open-text" style="font-size:48px; color:#0b57d0; margin-bottom:16px;"></i>
                <h2>E-mail enviado!</h2>
                <p>Verifique sua caixa de entrada em <strong>${e}</strong> e clique no link para criar uma nova senha.</p>
            </div>
        `}),f.auth.onAuthStateChange((t,e)=>{t==="PASSWORD_RECOVERY"&&(s.classList.add("hidden"),u.classList.remove("hidden"))});const d=document.getElementById("novaSenhaForm"),n=d.querySelector("button[type=submit]");d.addEventListener("submit",async t=>{t.preventDefault();const e=document.getElementById("newPassword").value,o=document.getElementById("confirmNewPassword").value;if(e!==o){alert("As senhas não coincidem. Tente novamente.");return}n.disabled=!0,n.textContent="Salvando...";const{error:l}=await m.updatePassword(e);if(l){alert(`Não foi possível atualizar a senha: ${l.message}`),n.disabled=!1,n.textContent="Modificar Senha e Acessar";return}alert("Senha atualizada com sucesso! Bem-vindo de volta."),window.location.href=c.perfil})});
